function toFormatDecimal1(inpNumber) {
	var pnumber = "";	
    var result = 0;	
	pnumber = inpNumber;
    var ktusauTphan = pnumber.lastIndexOf(".");
    var chuoi = pnumber.split(".");
    var gtri = chuoi[1];
	     var num = formatNumberUSD1(chuoi[0]);
    if (ktusauTphan ==  - 1) {
        result = num;
    }
    else {
        result = num + "," + gtri;
        if (gtri.length > 2) {
           result = result.replace(",","");
           result = result.replace(".",",");
            result = financial(result);
            var kq_c= result.split(".");
            result = formatNumberUSD1(kq_c[0])+","+kq_c[1];
        }
      
    }
	return result;
}
  
