function formatVar(inpVar){
	 var strReturn = "";
		var node = inpVar.nextNode();	
	try{
		if(node.hasChildNodes())
		{
	
	   vstrInput = node.childNodes[0].nodeValue;
		   if(vstrInput!="Khác")
		   {
		   strReturn =vstrInput + '%';
		   } 
		   else strReturn =vstrInput;
		 }
		}
		catch(e)
		{
		
		}
		if(strReturn==null)
		{
		strReturn = "";
		}
	return strReturn ;
}

